/**
* @brief  This function handles UART interrupt request.
* @param  huart  Pointer to a UART_HandleTypeDef structure that contains
*                the configuration information for the specified UART module.
* @retval None
*/
void HAL_UART_IRQHandler(UART_HandleTypeDef *huart)
{
  /* In emulation environment, simulate UART interrupt handling */

  /* Check if we're in receive mode and should receive data */
  if (huart->RxState == HAL_UART_STATE_BUSY_RX)
  {
    /* Simulate receiving data from stdin */
    int bytes_read = HAL_BE_In(huart->pRxBuffPtr, huart->RxXferCount);

    if (bytes_read > 0)
    {
      /* Update buffer pointer and count */
      huart->pRxBuffPtr += bytes_read;
      huart->RxXferCount -= bytes_read;

      /* If all data received, complete the transfer */
      if (huart->RxXferCount == 0U)
      {
        huart->RxState = HAL_UART_STATE_READY;
        huart->RxEventType = HAL_UART_RXEVENT_TC;

        /* Call appropriate callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
        if (huart->ReceptionType == HAL_UART_RECEPTION_TOIDLE)
        {
          huart->RxEventCallback(huart, huart->RxXferSize);
        }
        else
        {
          huart->RxCpltCallback(huart);
        }
#else
        if (huart->ReceptionType == HAL_UART_RECEPTION_TOIDLE)
        {
          HAL_UARTEx_RxEventCallback(huart, huart->RxXferSize);
        }
        else
        {
          HAL_UART_RxCpltCallback(huart);
        }
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
      }
    }
    return;
  }

  /* Check if we're in transmit mode */
  if (huart->gState == HAL_UART_STATE_BUSY_TX)
  {
    /* Transmit complete - update state */
    huart->gState = HAL_UART_STATE_READY;

    /* Call transmit complete callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
    huart->TxCpltCallback(huart);
#else
    HAL_UART_TxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */

    return;
  }

  /* Handle error conditions if needed */
  if (huart->ErrorCode != HAL_UART_ERROR_NONE)
  {
    /* Call error callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
    huart->ErrorCallback(huart);
#else
    HAL_UART_ErrorCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */

    huart->ErrorCode = HAL_UART_ERROR_NONE;
    return;
  }
}
